71	/// These elements are effectively always self-closing. They should not have a closing tag (if they do, it should be a parsing error). They might not contain a `/` like in `<img />`.
72	static VOID_ELEMENTS: &[&str] = &[
73	    "area", "base", "br", "col", "embed", "hr", "img", "input", "link", "meta", "param", "source",
74	    "track", "wbr",
