80	pub(crate) fn parse_root(p: &mut HtmlParser) {
81	    let m = p.start();
82	
83	    p.eat(UNICODE_BOM);
84	
85	    if p.at(T![---]) {
86	        HtmlSyntaxFeatures::Astro
87	            .parse_exclusive_syntax(
88	                p,
89	                |p| parse_astro_fence(p),
90	                |p, m| {
91	                    p.err_builder("Frontmatter is only valid inside Astro files.", m.range(p))
92	                        .with_hint("Remove it or rename the file to have the .astro extension.")
93	                },
94	            )
95	            .ok();
96	    }
97	
98	    // Whether or not frontmatter was present, once we're past the frontmatter
99	    // position `---` can no longer start a fence. This prevents `---` in HTML
100	    // content from being incorrectly lexed as a FENCE token.
101	    p.set_after_frontmatter(true);
102	
103	    parse_doc_type(p).ok();
104	    ElementList.parse_list(p);
105	
106	    m.complete(p, HTML_ROOT);
107	}
108	
109	fn parse_doc_type(p: &mut HtmlParser) -> ParsedSyntax {
110	    if !(p.at(T![<]) && p.nth_at(1, T![!])) {
111	        return Absent;
112	    }
113	
114	    let m = p.start();
115	    p.bump_with_context(T![<], HtmlLexContext::InsideTag);
116	    p.bump_with_context(T![!], HtmlLexContext::Doctype);
117	
118	    if p.at(T![doctype]) {
119	        p.eat_with_context(T![doctype], HtmlLexContext::Doctype);
120	    }
121	
122	    if p.at(T![html]) {
123	        p.eat_with_context(T![html], HtmlLexContext::Doctype);
124	    }
125	
126	    if p.at(HTML_LITERAL) {
127	        p.eat_with_context(HTML_LITERAL, HtmlLexContext::Doctype);
128	    }
129	
130	    if p.at(HTML_STRING_LITERAL) {
131	        p.eat_with_context(HTML_STRING_LITERAL, HtmlLexContext::Doctype);
132	    }
133	
134	    if p.at(HTML_STRING_LITERAL) {
135	        p.eat_with_context(HTML_STRING_LITERAL, HtmlLexContext::Doctype);
136	    }
137	
138	    p.eat(T![>]);
139	
140	    Present(m.complete(p, HTML_DIRECTIVE))
141	}
