170	/// Returns the lexer context to use when parsing component names and member expressions.
171	/// This allows `.` to be lexed as a token for member expressions like Component.Member
172	/// We reuse [HtmlLexContext::InsideTagWithDirectives] context because it supports `.` lexing, but this is ONLY used
173	/// for parsing component names, not for parsing attributes.
174	#[inline(always)]
175	fn component_name_context(p: &HtmlParser) -> HtmlLexContext {
176	    if Vue.is_supported(p) || Svelte.is_supported(p) || Astro.is_supported(p) {
177	        // Use HtmlLexContext::InsideTagWithDirectives for all component-supporting files when parsing component names
178	        // This allows `.` to be lexed properly for member expressions
179	        // Note: This is safe because we only use this context for tag names, not attributes
180	        HtmlLexContext::InsideTagWithDirectives {
181	            svelte: Svelte.is_supported(p),
182	        }
183	    } else {
184	        HtmlLexContext::InsideTag
185	    }
186	}
