349	/// Checks whether the parser is positioned at a closing tag for a void element,
350	/// e.g. `</br>` or `</input>`.
351	///
352	/// Void elements are always self-closing and must never have a closing tag, so
353	/// such a tag needs to be treated as a bogus element rather than as the closing
354	/// tag of an enclosing element. See [`parse_void_element_closing_tag`].
355	fn is_at_void_closing_tag(p: &mut HtmlParser) -> bool {
356	    if !p.at(T![<]) || !p.nth_at(1, T![/]) {
357	        return false;
358	    }
359	
360	    // We need to inspect the tag name, which requires lexing past `</` using the
361	    // inside-tag context. Do so behind a checkpoint so we can rewind afterwards.
362	    let checkpoint = p.checkpoint();
363	    p.bump_with_context(T![<], HtmlLexContext::InsideTag);
364	    p.bump_with_context(T![/], HtmlLexContext::InsideTag);
365	    let is_void = is_at_start_literal(p)
366	        && VOID_ELEMENTS
367	            .iter()
368	            .any(|tag| tag.eq_ignore_ascii_case(p.cur_text()))
369	        && !is_possible_component(p, p.cur_text());
370	    p.rewind(checkpoint);
371	
372	    is_void
373	}
