375	/// Parses a closing tag for a void element (e.g. `</br>`) as an [`HtmlBogusElement`]
376	/// and emits a single diagnostic covering the entire closing tag.
377	///
378	/// The tag is intentionally *not* treated as the closing tag of any enclosing
379	/// element, so the surrounding document hierarchy is preserved and the parent's
380	/// own matching closing tag still closes it normally.
381	fn parse_void_element_closing_tag(p: &mut HtmlParser) -> ParsedSyntax {
382	    let m = p.start();
383	    p.bump_with_context(T![<], inside_tag_context(p));
384	    p.bump_with_context(T![/], inside_tag_context(p));
385	    parse_any_tag_name(p).ok();
386	    // Whitespace before `>` is lexed as trivia, so this also handles closing
387	    // tags with trailing spaces such as `</br >`.
388	    p.expect(T![>]);
389	    let closing_tag = m.complete(p, HTML_BOGUS_ELEMENT);
390	    p.error(void_element_should_not_have_closing_tag(p, closing_tag.range(p)).into_diagnostic(p));
391	    Present(closing_tag)
392	}
